  context,
  node,
  templateContent,
}: {
  context: SupabaseContext;
  node: DiscourseNode;
  templateContent?: string;
}): LocalConceptDataInput => {
  const {
    description,
    template,
    id,
    name,
    created,
    modified,
    importedFromRid,
    ...otherData
  } = node;
  const literal_content: Record<string, Json> = {
    label: name,
