    space_id: context.spaceId,
    name,
    source_local_id: id,
    is_schema: true,
    author_id: context.userId,
    created: new Date(created).toISOString(),
    last_modified: new Date(modified).toISOString(),
    description: description,
    literal_content,
  };
};

